using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using System.Collections.Generic;
// Controller adapter retains the same gameplay actions and mouse-driven inventory/wiring UI.
[DefaultExecutionOrder(-1000)]
public class WoodlandDemoControls:MonoBehaviour {
 public static bool Paused;Keyboard padKeyboard;Mouse padMouse;bool controller;Vector2 pointer;WoodlandPlayer player;int menuChoice;bool resumeUnlock;CursorLockMode beforePause;public static bool UsingController;public static bool FocusRequested;public static float AimSensitivity=1f;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Boot(){if(!Object.FindFirstObjectByType<WoodlandDemoControls>()){var g=new GameObject("Demo controls");Object.DontDestroyOnLoad(g);g.AddComponent<WoodlandDemoControls>();}}
 void Awake(){FocusRequested=false;AimSensitivity=Mathf.Clamp(PlayerPrefs.GetFloat("ControllerAimSensitivity",1f),.5f,1.5f);Paused=false;Time.timeScale=1;pointer=new Vector2(Screen.width/2,Screen.height/2);InputSystem.onBeforeUpdate+=ReadPad;}
 void ReadPad(){var p=Gamepad.current;if(p==null)return;if(!controller){if(p.leftStick.ReadValue().magnitude<.15f&&p.rightStick.ReadValue().magnitude<.15f&&!p.allControls.ExistsPressed())return;controller=true;}UsingController=controller;if(padKeyboard==null){padKeyboard=InputSystem.AddDevice<Keyboard>("Xbox action keyboard");padMouse=InputSystem.AddDevice<Mouse>("Xbox pointer");}var keys=new List<Key>();bool ui=Cursor.lockState!=CursorLockMode.Locked;bool modifier=p.leftShoulder.isPressed;
 if(p.leftStickButton.isPressed)keys.Add(Key.LeftShift);if(p.leftTrigger.isPressed)keys.Add(Key.Q);
 if(p.buttonWest.isPressed)keys.Add(Key.R);if(p.buttonSouth.isPressed&&!ui)keys.Add(Key.E);if(p.buttonEast.isPressed&&!Paused)keys.Add(Key.B);if(p.buttonNorth.isPressed)keys.Add(Key.F);
 if(p.rightShoulder.isPressed)keys.Add(modifier?Key.P:Key.H);
 if(p.dpad.up.isPressed)keys.Add(modifier?Key.Digit1:Key.T);if(p.dpad.left.isPressed)keys.Add(modifier?Key.Digit2:Key.Z);if(p.dpad.right.isPressed)keys.Add(modifier?Key.Digit3:Key.X);if(p.dpad.down.isPressed)keys.Add(modifier?Key.C:Key.Y);
 if(p.selectButton.isPressed)keys.Add(Key.G);if(p.buttonSouth.isPressed&&player&&(player.anatomy.Incapacitated||player.cinematicLocked))keys.Add(Key.Enter);
 InputSystem.QueueStateEvent(padKeyboard,new KeyboardState(keys.ToArray()));var stick=p.rightStick.ReadValue();var delta=ui?stick*650*Time.unscaledDeltaTime:Vector2.zero;pointer+=delta;pointer.x=Mathf.Clamp(pointer.x,0,Screen.width);pointer.y=Mathf.Clamp(pointer.y,0,Screen.height);var state=new MouseState{position=pointer,delta=ui?Vector2.zero:delta};state=state.WithButton(MouseButton.Left,!Paused&&(ui?p.buttonSouth.isPressed:p.rightTrigger.isPressed));InputSystem.QueueStateEvent(padMouse,state);
 }
 void Update(){var aimPad=Gamepad.current;if(aimPad==null||!aimPad.leftTrigger.isPressed)FocusRequested=false;else if(!Paused&&aimPad.rightStickButton.wasPressedThisFrame)FocusRequested=!FocusRequested;if(!player)player=Object.FindFirstObjectByType<WoodlandPlayer>();var pad=Gamepad.current;bool toggle=pad!=null&&pad.startButton.wasPressedThisFrame||Keyboard.current!=null&&Keyboard.current.escapeKey.wasPressedThisFrame;
 if(toggle){if(Paused)Resume();else{beforePause=Cursor.lockState;Paused=true;Time.timeScale=0;AudioListener.pause=true;Cursor.lockState=CursorLockMode.None;Cursor.visible=true;}}
 if(Paused&&pad!=null){if(pad.dpad.left.wasPressedThisFrame)AdjustAim(-.1f);if(pad.dpad.right.wasPressedThisFrame)AdjustAim(.1f);if(pad.dpad.up.wasPressedThisFrame||pad.dpad.down.wasPressedThisFrame)menuChoice=1-menuChoice;if(pad.buttonEast.wasPressedThisFrame)Resume();else if(pad.buttonSouth.wasPressedThisFrame){if(menuChoice==0)Resume();else Application.Quit();}}
 }
 public static void AdjustAim(float change){AimSensitivity=Mathf.Clamp(Mathf.Round((AimSensitivity+change)*10)/10,.5f,1.5f);PlayerPrefs.SetFloat("ControllerAimSensitivity",AimSensitivity);PlayerPrefs.Save();}
 void Resume(){Paused=false;Time.timeScale=1;AudioListener.pause=false;Cursor.lockState=beforePause;Cursor.visible=beforePause!=CursorLockMode.Locked;}
 void OnGUI(){if(UsingController&&Cursor.lockState!=CursorLockMode.Locked){GUI.depth=-2000;GUI.color=Color.white;GUI.DrawTexture(new Rect(pointer.x-3,Screen.height-pointer.y-3,6,6),Texture2D.whiteTexture);}if(!Paused)return;GUI.depth=-1000;GUI.color=new Color(0,0,0,.94f);GUI.DrawTexture(new Rect(0,0,Screen.width,Screen.height),Texture2D.whiteTexture);GUI.color=Color.white;float x=Screen.width*.15f,w=Screen.width*.7f;var s=new GUIStyle(GUI.skin.label){fontSize=18,wordWrap=true};GUI.Label(new Rect(x,35,w,40),"THE SICKNESS — PAUSED",s);GUI.Label(new Rect(x,90,w,450),"XBOX CONTROLLER\nLeft stick: move · L3: sprint · Right stick: look\nLT: aim · R3 while aiming: toggle focus · RT: fire\nX: reload · A: interact · B: backpack · Y: torch (double tap changes colour)\nD-pad left/right: lean while aiming · Up: hold to inspect watch · Down: glow stick\nHold RB: bandage · LB + RB: patch suit\nLB + D-pad up/left/right: rifle / radio / handheld torch\nLB + D-pad down: wipe visor · View: companion · Menu: pause\n\nBACKPACK / GENERATOR\nRight stick: pointer · A: click or hold to drag · B: backpack close\n\nKEYBOARD / MOUSE\nWASD: move · Shift: sprint/focus · Q: aim · Mouse: look/fire\nR: reload · E: interact · B: backpack · F: torch · T: watch\nH: bandage · P: patch · C: wipe · Y: glow stick · Z/X: lean\n1/2/3: rifle/radio/torch · G: companion · Esc: pause",s);GUI.Label(new Rect(x,Screen.height-170,w,30),"ADS sensitivity: "+AimSensitivity.ToString("0.0")+"×   ·   D-pad left / right to adjust",s);if(GUI.Button(new Rect(x+w-100,Screen.height-170,45,30),"−"))AdjustAim(-.1f);if(GUI.Button(new Rect(x+w-50,Screen.height-170,45,30),"+"))AdjustAim(.1f);if(GUI.Button(new Rect(x,Screen.height-110,220,45),(menuChoice==0?"> ":"")+"Resume / Menu / B"))Resume();if(GUI.Button(new Rect(x+240,Screen.height-110,180,45),(menuChoice==1?"> ":"")+"Quit demo"))Application.Quit();}
 void OnDestroy(){InputSystem.onBeforeUpdate-=ReadPad;if(padKeyboard!=null)InputSystem.RemoveDevice(padKeyboard);if(padMouse!=null)InputSystem.RemoveDevice(padMouse);Time.timeScale=1;AudioListener.pause=false;Paused=false;UsingController=false;FocusRequested=false;}
}
public static class PadControlExtensions{public static bool ExistsPressed(this UnityEngine.InputSystem.Utilities.ReadOnlyArray<UnityEngine.InputSystem.InputControl> controls){foreach(var c in controls)if(c is UnityEngine.InputSystem.Controls.ButtonControl b&&b.isPressed)return true;return false;}}
